  // --- Events ---

  getEvents(communityId: string): Observable<CommunityEvent[]> {
    return this.eventsSubject.pipe(
      map(list => list.filter(e => e.communityId === communityId))
    );
  }

  searchEvents(communityId: string, term: string): Observable<CommunityEvent[]> {
    return this.getEvents(communityId).pipe(
      map(list => {
        if (!term) return list;
        const lower = term.toLowerCase();
        return list.filter(e =>
          e.title.toLowerCase().includes(lower) ||
          e.description.toLowerCase().includes(lower) ||
          e.location.toLowerCase().includes(lower) ||
          e.organizerName.toLowerCase().includes(lower) ||
          (e.tags || []).some(t => t.toLowerCase().includes(lower))
        );
      })
    );
  }

  getEvent(eventId: string): Observable<CommunityEvent | undefined> {
    return this.eventsSubject.pipe(
      map(list => list.find(e => e.id === eventId))
    );
  }

  createEvent(data: Partial<CommunityEvent>): Observable<CommunityEvent> {
    const newEvent: CommunityEvent = {
      id: `evt-new-${this.nextId++}`,
      communityId: data.communityId || '',
      title: data.title || '',
      description: data.description || '',
      imageUrl: data.imageUrl,
      date: data.date || new Date(),
      endDate: data.endDate,
      location: data.location || '',
      isOnline: data.isOnline || false,
      meetingUrl: data.meetingUrl,
      organizerId: 'current-user',
      organizerName: '自分',
      maxParticipants: data.maxParticipants,
      participantCount: 1,
      participants: [{ id: 'current-user', name: '自分' }],
      tags: data.tags,
      createdAt: new Date(),
    };
    const current = this.eventsSubject.getValue();
    this.eventsSubject.next([newEvent, ...current]);
    return of(newEvent).pipe(delay(200));
  }

  joinEvent(eventId: string): Observable<void> {
    const current = this.eventsSubject.getValue();
    const updated = current.map(e => {
      if (e.id === eventId) {
        const alreadyJoined = e.participants.some(p => p.id === 'current-user');
        if (alreadyJoined) return e;
        return {
          ...e,
          participantCount: e.participantCount + 1,
          participants: [...e.participants, { id: 'current-user', name: '自分' }],
        };
      }
      return e;
    });
    this.eventsSubject.next(updated);
    return of(undefined).pipe(delay(200));
  }

