// --- Author info lookup from members ---
const memberMap = new Map(MOCK_MEMBERS.map(m => [m.id, m]));

function enrichAuthor<T extends { authorId: string }>(item: T): T {
  const member = memberMap.get(item.authorId);
  if (member) {
    return { ...item, authorAvatar: member.avatar, authorCompany: member.company, authorJobTitle: member.jobTitle };
  }
  return item;
}

